local entries = ref.kinds["spell"]["deDE"]
entries[79896] = { ["name"] = "Heulende Böe", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nWeht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden." }
entries[79897] = { ["name"] = "Eisige Berührung", ["text"] = "20 Meter Reichweite\nSofort\nVerursacht Frostschaden und verringert 8 Sek. lang das Nahkampf-, Distanzangriffs- und Zaubertempo des Ziels um 15%." }
entries[79898] = { ["name"] = "Corrupted Body (Self)" }
entries[79899] = { ["name"] = "Eisketten", ["text"] = "25 Meter Reichweite\nSofort 8 sek. Abklingzeit\nUmschlingt das Ziel mit eisigen Ketten und verringert sein Bewegungstempo auf 5% des Normalwerts. Das Ziel erhält im Verlauf von 10 Sek. pro Sekunde 10% seines Bewegungstempos zurück." }
entries[79900] = { ["name"] = "Instabiler Schild", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nAngriffe auf den instabilen Schild verursachen einen statischen Schock am Standort eines nahen Feindes. Der statische Schock fügt Feinden im Umkreis von 6 Metern um das Ziel 58500 to 61500 Naturschaden zu.\n(250ms Abklingzeit)" }
entries[79901] = { ["name"] = "Blutseuche", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der Waffenschaden verursacht, das Ziel verseucht und ihm so im Verlauf von 12 Sek. Schattenschaden zufügt." }
entries[79902] = { ["name"] = "Seuchenstoß", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der Waffenschaden verursacht, das Ziel verseucht und im Verlauf von 12 Sek. 8000 Schattenschaden hervorruft." }
entries[79903] = { ["name"] = "Todesmantel", ["text"] = "45 Meter Reichweite\nWirken in 1.5 sek.\nFügt einem zufälligen nahen Ziel 24 to 29 Schattenschaden zu." }
entries[79904] = { ["name"] = "Sturmangriff", ["text"] = "45 Meter Reichweite\nSofort 3 sek. Abklingzeit\nStürmt auf einen Gegner zu, fügt ihm sowie seinen nahen Verbündeten 13423 to 15600 Schaden zu und stößt alle betroffenen Ziele zurück." }
entries[79905] = { ["name"] = "Totenerweckung", ["text"] = "30 Meter Reichweite\nSofort\nErweckt einen Ghul, der an Eurer Seite kämpft. Steht kein humanoider Leichnam zur Verfügung, der Erfahrung oder Ehre gewährt, wird Leichenstaub benötigt, um den Zauber zu wirken. Ihr könnt nur maximal einen Ghul gleichzeitig beschwören. Hält 1 Min. lang" }
entries[79907] = { ["name"] = "Antimagisches Feld", ["text"] = "1 Unheilige Rune\nSpontanzauber\nPlatziert ein großes, ortsgebundenes, antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 75% verringert. Das antimagische Feld hält 10 Sek. lang an oder bis es (10000 + 2 * Attack power) Zauberschaden absorbiert hat." }
entries[79908] = { ["name"] = "Statischer Schock" }
entries[79909] = { ["name"] = "Geißelstoß", ["text"] = "1 Unheilige Rune / -10 Runenmacht Nahkampfreichweite\nSpontanzauber\nEin unheiliger Stoß, der 150% Waffenschaden in Form von Schattenschaden verursacht." }
entries[79910] = { ["name"] = "Instabiler Schild" }
entries[79911] = { ["name"] = "Statischer Schock" }
entries[79912] = { ["name"] = "Statischer Schock", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt Gegnern im Umkreis von 6 Metern 58500 to 61500 Naturschaden zu." }
entries[79913] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 3 Ziele aus und verursacht bei jedem folgenden Ziel immer geringeren Naturschaden." }
entries[79914] = { ["name"] = "Wildgeist", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort\nBeschwört zwei Geisterwölfe, die unter dem Befehl des Schamanen stehen. Hält 45 Sek. lang an." }
entries[79919] = { ["name"] = "Trägt ein Samophlang", ["text"] = "Sofort\nHält sein Samophlang voller Stolz in die Höhe." }
entries[79920] = { ["name"] = "Geteilte Gesundheit" }
entries[79921] = { ["name"] = "Schattenflamme", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 3 sek.) 3 sek. Abklingzeit\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 23125 to 26875 Feuerschaden zu." }
entries[79922] = { ["name"] = "Schinden", ["text"] = "Wirken in 0.6 sek.\nFügt allen Feinden im Umkreis von 4 Metern alle 0,25 Sek. 60% Waffenschaden zu. Hält 5 Sek. lang an." }
entries[79923] = { ["name"] = "Schinden", ["text"] = "Sofort\nFügt allen Feinden im Umkreis von 4 Metern alle 0,25 Sek. 60% Waffenschaden zu. Hält 5 Sek. lang an." }
entries[79924] = { ["name"] = "Welle der Heilung", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft Naturmagie herbei, um einen Verbündeten zu heilen." }
entries[79925] = { ["name"] = "Frostschock", ["text"] = "25 Mana 20 Meter Reichweite\nSofort\nFügt einem Feind Frostschaden zu und verringert 6 Sek. lang sein Bewegungstempo." }
entries[79926] = { ["name"] = "Urtümlicher Schlag", ["text"] = "8% von Grundmana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin sofortiger Waffenstoß, der 20 zusätzlichen Schaden verursacht." }
entries[79927] = { ["name"] = "Erdschild", ["text"] = "40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf. 10 Aufladungen. Hält 10 Min. lang an.\n(3.5s Abklingzeit)" }
entries[79928] = { ["name"] = "Erdschild", ["text"] = "Sofort\nSchützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf." }
entries[79929] = { ["name"] = "Blutfratzen suchen" }
entries[79930] = { ["name"] = "Verderbnis", ["text"] = "25 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerdirbt in der Nähe befindliche Feinde und fügt ihnen 15 Sek. lang alle 3 Sek. Schattenschaden zu." }
entries[79931] = { ["name"] = "Defeat Crushcog Credit" }
entries[79932] = { ["name"] = "Schattenblitz", ["text"] = "15 Mana 40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
entries[79933] = { ["name"] = "Blutsauger", ["text"] = "30 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nEntzieht einem Gegner im Verlauf von 5 Sek. Gesundheit und überträgt sie auf den Zaubernden." }
entries[79934] = { ["name"] = "Dämonenrüstung", ["text"] = "31% von Grundmana\nSofort\nBeschützt den Zaubernden, erhöht seine Rüstung sowie die Menge an wiederhergestellter Gesundheit durch Zauber und Effekte um 20%. Es kann immer nur ein Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an." }
entries[79936] = { ["name"] = "Slam Smoot" }
entries[79937] = { ["name"] = "Feuerbrand", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt sofort einen Feind und fügt ihm dann 15 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[79938] = { ["name"] = "Verbrennen", ["text"] = "15 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nFügt Eurem Ziel Feuerschaden zu." }
entries[79939] = { ["name"] = "Chaosblitz", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz chaotischen Feuers auf den Gegner und verursacht Feuerschaden. Dem Chaosblitz kann nicht widerstanden werden und er durchbricht defensive Immunitäten." }
entries[79948] = { ["name"] = "Summon Samophlange" }
entries[79949] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 10 Mana gewähren. Trifft ein Zauber, ein Nahkampf- oder Distanzangriff den Zaubernden, erhält er 758 Mana und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[79950] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 10 Mana gewähren. Trifft ein Zauber, ein Nahkampf- oder Distanzangriff den Zaubernden, erhält er 758 Mana und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein." }
entries[79952] = { ["name"] = "Be Raptor: Summon Raptor 1" }
entries[79953] = { ["name"] = "Be Raptor: Forcecast Teleport In (Master)" }
entries[79954] = { ["name"] = "Teufelsrüstung", ["text"] = "28% von Grundmana\nSofort\nUmgibt Euch mit Teufelsenergie, welche Eure Zaubermacht um 10% erhöht. Zusätzlich regeneriert Ihr alle 5 Sek. 2% Eurer gesamten Gesundheit. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an." }
entries[79955] = { ["name"] = "Feuerregen", ["text"] = "35 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde im ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. Feuerschaden zufügt." }
entries[79956] = { ["name"] = "Fluch der Elemente", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel 30 Sek. lang und verringert so seinen Widerstand gegen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden um 45, während der erlittene Magieschaden um 8% erhöht wird. Es kann immer nur jeweils ein Fluch pro Zauberndem auf einem beliebigen Ziel aktiv sein." }
entries[79957] = { ["name"] = "Seelenverbindung", ["text"] = "16% von Grundmana 100 Meter Reichweite\nSofort\nBei Aktivierung werden 20% des von Euch erlittenen Schadens auf Euren Wichtel, Leerwandler, Sukkubus, Teufelsjäger, Teufelswache oder versklavten Dämon umgelenkt. Dieser Schaden kann nicht vermieden werden. Hält an, solange der Dämon aktiv ist und kontrolliert wird." }
entries[79958] = { ["name"] = "Teufelswache beschwören", ["text"] = "80% von Grundmana\nSofort\nBeschwört einen Teufelswächter unter dem Befehl des Zaubernden." }
entries[79960] = { ["name"] = "Heiliges Licht", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[79961] = { ["name"] = "Heiliger Schock", ["text"] = "25 Mana 30 Meter Reichweite\nSofort\nÜberzieht das Ziel mit heiliger Energie und fügt einem Feind Heiligschaden zu." }
entries[79962] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Zaubernden 30 Min. lang mit heiligem Geist, durch den jeder Einzelziel-Nahkampfangriff zusätzlichen Heiligschaden verursacht." }
entries[79963] = { ["name"] = "Aura der Konzentration", ["text"] = "Sofort\nVerbündete im Umkreis von 40 Metern verlieren bei erlittenem Schaden 35% weniger Zauber- und Kanalisierungszeit." }
entries[79964] = { ["name"] = "Exorzismus", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nFügt einem Gegner Heiligschaden zu." }
entries[79965] = { ["name"] = "Schild des Rächers", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen heiligen Schild nach dem Feind, der ihm Heiligschaden zufügt, ihn benommen macht und dann auf weitere nahe Feinde überspringt. Trifft bis zu 2 Ziele insgesamt." }
entries[79966] = { ["name"] = "Weihe", ["text"] = "22% von Grundmana\nSofort\nWeiht das Land unter dem Zaubernden fügt 8 Sek. lang Feinden, die das Gebiet betreten, Heiligschaden zu." }
entries[79967] = { ["name"] = "Heiliger Schild", ["text"] = "10% von Grundmana\nSofort\nErhöht die Blockchance 10 Sek. lang um 30% und verursacht, während der Effekt aktiv ist, mit jedem Blocken Heiligschaden. Jedes Blocken zehrt eine Aufladung auf. 3 Aufladungen." }
entries[79968] = { ["name"] = "Segen der Könige", ["text"] = "30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen, welcher 5 Min. lang seine Stärke, Beweglichkeit, Ausdauer und Intelligenz um 5% erhöht." }
entries[79970] = { ["name"] = "Göttlicher Sturm", ["text"] = "20% von Grundmana Nahkampfreichweite\nSofort\nEin sofortiger Waffenangriff, der bei bis zu 4 Feinden innerhalb von 8 Metern Heiligschaden verursacht." }
entries[79971] = { ["name"] = "Hammer des Zorns", ["text"] = "30 Mana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Hammer, der einem Gegner Heiligschaden zufügt." }
entries[79972] = { ["name"] = "Siegel der Wahrheit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin mit heiliger Macht, durch den Angriffe auf Einzelziele den Effekt 'Tadel' auslösen, der im Verlauf von 15 Sek. [(0.01 * Spell power + 0.0193 * Attack power) * 5 */ 100] zusätzlichen Heiligschaden verursacht. 'Tadel' ist bis zu 5-mal stapelbar. Sobald 5 Stapel erreicht werden, verursacht jeder Angriff des Paladins zusätzlich 15% Waffenschaden als Heiligschaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 5 Min. lang an.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind (1 + 0.223 * Spell power + 0.142 * Attack power) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Tadel' auf dem Ziel um 10% erhöht." }
entries[79973] = { ["name"] = "Wirbelwind", ["text"] = "Kanalisiert (Wirken in 5 sek.)\nFügt Feinden vor dem Zaubernden alle 1 Sek. 32987 to 37012 Schaden zu." }
entries[79974] = { ["name"] = "Wirbelwind", ["text"] = "Sofort\nFügt Feinden vor dem Zaubernden alle 1 Sek. 32987 to 37012 Schaden zu." }
entries[79975] = { ["name"] = "Gedankenkontrolle von Zul'Gurub", ["text"] = "Unbegrenzte Reichweite\nSofort\nErlaubt es Euch, das gefangene Schmetterschwanzjunge zu kontrollieren." }
entries[79976] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nFügt jeder Kreatur, die den Zaubernden trifft, Heiligschaden zu." }
entries[79977] = { ["name"] = "Segen der Macht", ["text"] = "30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen, welcher 5 Min. lang seine Angriffskraft um 20%, seine Distanzangriffskraft um 10% erhöht und alle 5 Sek. 1 Mana regeneriert." }
entries[79983] = { ["name"] = "Summon Earthguard Elemental" }
entries[80003] = { ["name"] = "Schwarzer Pfeil", ["text"] = "35 Meter Reichweite\nBenötigt Distanzwaffe\nFeuert einen schwarzen Pfeil auf das Ziel ab, der Euren verursachten Schaden gegen das Ziel um 6% erhöht und 15 Sek. lang Schattenschaden verursacht." }
entries[80004] = { ["name"] = "Schlangenfalle", ["text"] = "Sofort\nEine Falle platzieren, die mehrere giftige Schlangen frei lässt, um den ersten Gegner anzugreifen, der sich nähert. Die Schlangen sterben nach 5 Sek. Die Falle besteht 1 Min. lang." }
entries[80005] = { ["name"] = "Sentinel Hill Skybox" }
entries[80007] = { ["name"] = "Schlangenfalle" }
entries[80008] = { ["name"] = "Summon Earthguard Elementalist (Reporting)" }
entries[80009] = { ["name"] = "Schlangengift", ["text"] = "40 Meter Reichweite\nBenötigt Distanzwaffe\nSticht das Ziel und verursacht 15 Sek. lang Naturschaden." }
entries[80010] = { ["name"] = "Taxi Path Flavor" }
entries[80011] = { ["name"] = "Giftgetränkt", ["text"] = "Unbegrenzte Reichweite\nSofort\nGiftgetränkt zu sein verursacht alle 2 Sek. 20000 Naturschaden und lässt Zauber und Fähigkeiten dem Ziel 19500 to 20500 Naturschaden zufügen.\n(500ms Abklingzeit)" }
entries[80012] = { ["name"] = "Schimärenschuss", ["text"] = "45% von Grundfokus 35 Meter Reichweite\n10 sek. Abklingzeit\nBenötigt Distanzwaffe\nVerursacht 125% Waffenschaden, frischt die Dauer Eures auf das Ziel wirkenden Gifts auf und löst einen Effekt aus:\n\nSchlangengift - Verursacht sofort 40% des von Eurer Fähigkeit 'Schlangengift' verursachten Schadens.\n\nViperngift - Stellt für Euch sofort Mana in Höhe von 60% des von Eurer Fähigkeit 'Viperngift' entzogenen Manas her.\n\nSkorpidgift - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nicht öfter als ein Mal pro Minute auftreten." }
entries[80013] = { ["name"] = "Schimärenschuss - Schlange", ["text"] = "100 Meter Reichweite\nVerursacht 0 % Waffenschaden, frischt die Dauer Eures auf das Ziel wirkenden Gifts auf und löst einen Effekt aus:\n\nSchlangengift - Verursacht sofort 40% des von Eurer Fähigkeit 'Schlangengift' verursachten Schadens.\n\nViperngift - Stellt für Euch sofort Mana in Höhe von 60% des von Eurer Fähigkeit 'Viperngift' entzogenen Manas her.\n\nSkorpidgift - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nicht öfter als ein Mal pro Minute auftreten." }
entries[80014] = { ["name"] = "Gift auslöschen", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt dem Ziel Eurer Zauber und Fähigkeiten 19500 to 20500 Naturschaden zu." }
entries[80015] = { ["name"] = "Zuverlässiger Schuss", ["text"] = "35 Meter Reichweite\nWirken in 1.5 sek.\nBenötigt Distanzwaffe\nEin gezielter Schuss, der Waffenschaden plus (Ranged attack power * 0.1 + 0) verursacht." }
entries[80016] = { ["name"] = "Mal des Jägers", ["text"] = "100 Meter Reichweite\nSofort\nBelegt das Ziel mit dem Mal des Jägers. Erhöht die Distanzschaden aller Angreifer gegen dieses Ziel um 10%. Zudem kann das Ziel dieser Fähigkeit stets vom Jäger gesehen werden, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 30 Sek. lang an." }
entries[80017] = { ["name"] = "Disziplinieren" }
entries[80018] = { ["name"] = "Frostfalle", ["text"] = "Sofort\nEine Frostfalle platzieren, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald der erste Feind sich ihr nähert. Das Bewegungstempo aller Feinde in einem Umkreis von 10 Metern wird um 50% verlangsamt, solange sie sich im Wirkungsbereich befinden. Die Falle bleibt 30 Sek. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[80019] = { ["name"] = "Frostfallenaura", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine Frostfalle platzieren, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald der erste Feind sich ihr nähert. Das Bewegungstempo aller Feinde in einem Umkreis von 10 Metern wird um 50% verlangsamt, solange sie sich im Wirkungsbereich befinden." }
entries[80020] = { ["name"] = "Zorn des Wildtiers", ["text"] = "10% von Grundmana 100 Meter Reichweite\nSofort\nVersetzt Euer Tier in einen Kampfrausch, wodurch es 18 Sek. lang 50% zusätzlichen Schaden verursacht. Einmal im Kampfrausch, gibt es keine Möglichkeit mehr, es zu stoppen, es sei denn, es wird getötet." }
entries[80021] = { ["name"] = "Netz", ["text"] = "30 Meter Reichweite\nSofort\nMacht einen Feind 4 Sek. lang bewegungsunfähig." }
entries[80022] = { ["name"] = "Netz durchbeißen", ["text"] = "Unbegrenzte Reichweite\nWirken in 0.5 sek.\nBeißt Euch durch die Netze der Trolle der Gurubashi. Funktioniert nicht bei Eisengewebten Netzen." }
entries[80028] = { ["name"] = "Fels bohren", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht alle 3 Sek. 4000 Schaden. Bis zu 10-mal stapelbar. Hält 15 Sek. lang an." }
entries[80031] = { ["name"] = "Flammende Scherbe", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Feind und seinem nächsten Verbündeten 110% des normalen Nahkampfschadens zu." }
entries[80035] = { ["name"] = "Rächende Wut", ["text"] = "100 Meter Reichweite\nSofort\nDer Tod eines Gefährten zieht einen Energieanstieg nach sich, erhöht den verursachten Schaden um 100% und das Angriffstempo 50%." }
entries[80038] = { ["name"] = "Magmaeruption", ["text"] = "150 Mana\nKanalisiert (Wirken in 3 sek.)\nSchleudert geschmolzenes Gestein, das allen Gegnern im Umkreis von 2 Metern um das Zielgebiet 56550 to 63450 Feuerschaden zufügt." }
entries[80039] = { ["name"] = "Magmaeruption" }
entries[80040] = { ["name"] = "Wimmelnder Boden" }
entries[80046] = { ["name"] = "Tikifeuer anzünden", ["text"] = "11 Meter Reichweite\nSofort\nReagenzien:\nBrennender Zweig\nSetzt ein Tiki von Zul'Gurub in Brand. Ihr müsst den Brennenden Zweig haben." }
entries[80049] = { ["name"] = "Schädel fallen lassen", ["text"] = "Unbegrenzte Reichweite\nSofort\nReagenzien:\nGurubashischädel\nLegt einen Schädel auf dem Boden ab. Ihr müsst einen Schädel der Gurubashi bei Euch tragen." }
entries[80051] = { ["name"] = "Schreckliche Wunde", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Angriff, der das Ziel stark bluten lässt, bis es um mehr als 90% seiner maximalen Gesundheit geheilt wird." }
entries[80052] = { ["name"] = "Magmaeruption", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert geschmolzenes Gestein, das allen Gegnern im Umkreis von 2 Metern um das Zielgebiet 56550 to 63450 Feuerschaden zufügt." }
entries[80053] = { ["name"] = "Giftprotokoll", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 9 sek.) 10 sek. Abklingzeit\nDas Giftprotokoll erschafft alle 3 Sek. eine Giftbombe, die bei Kontakt mit ihrem Ziel oder nachdem sie zerstört wurde explodiert." }
entries[80054] = { ["name"] = "Brockeneinschlag" }
