entries[80719] = { ["name"] = "Fläschchen der Stahlhaut", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Aschenblüte (8), Schattenjasmin (8), Kristallphiole\n80\nBenutzen: Erhöht die Ausdauer 1 Stunde lang um 450. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[80720] = { ["name"] = "Fläschchen der drakonischen Gedanken", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Azsharas Schleier (8), Schattenjasmin (8), Kristallphiole\n80\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 300. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[80721] = { ["name"] = "Fläschchen der Winde", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Azsharas Schleier (8), Gertenrohr (8), Kristallphiole\n80\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 300. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[80722] = { ["name"] = "Bürde der Krone", ["text"] = "20 Meter Reichweite\nSofort\nErhöht den verursachten Schaden um 100%.\nFähigkeiten sind kostenlos, verursachen jedoch pro Treffer 13875 to 16125 Schaden." }
entries[80723] = { ["name"] = "Fläschchen der Titanenstärke", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Aschenblüte (8), Gertenrohr (8), Kristallphiole\n80\nBenutzen: Erhöht die Stärke 1 Stunde lang um 300. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[80724] = { ["name"] = "Fläschchen der Verstärkung", ["text"] = "Wirken in 1.5 sek. 5\nReagenzien:\nAschenblüte (8), Sturmwinde (8), Azsharas Schleier (8), Gertenrohr (8), Schattenjasmin (8), Kristallphiole\nFläschchen der Verstärkung\nWird beim Aufheben gebunden\nBenötigt Alchemie\n(500)\nBenutzen: Erhöht Eure Beweglichkeit, Stärke oder Intelligenz 2 Stunden lang um 80. Es wird stets Euer höchster Wert gewählt.\n\nGilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\"Kann in Arenen verwendet werden. Dieses machtvolle Fläschchen wird bei der Nutzung nicht verbraucht, profitiert jedoch nicht von Mixologie.\"" }
entries[80725] = { ["name"] = "Trank von Tiefenheim", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nHerzblüte (5), Kristallphiole\n82\nBenutzen: Teleportiert den Trinkenden nach Tiefenheim. (1 Min Abklingzeit)" }
entries[80726] = { ["name"] = "Trank des Schätzefindens", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAschenblüte (8), Sturmwinde (4), Herzblüte (6), Gertenrohr (4), Kristallphiole\n80\nBenutzen: Gestattet es Euch, manchmal zusätzliche Beute von Monstern auf dem Hyjal, in Vashj'ir, in Tiefenheim, im Schattenhochland und in Uldum zu bekommen. Hält 1 Stunde lang an. Dieser Effekt hält über den Tod hinaus an. (1 Min Abklingzeit)" }
